import { Injectable, inject, signal, computed } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { toObservable } from '@angular/core/rxjs-interop';

@Injectable({ providedIn: 'root' })
export class ThemeService {
  private readonly document = inject(DOCUMENT);

  private readonly _isDark = signal<boolean>(false);
  readonly isDark = this._isDark.asReadonly();
  readonly isDark$ = toObservable(this._isDark);

  readonly theme = computed<'dark' | 'light'>(() =>
    this._isDark() ? 'dark' : 'light',
  );
  readonly themeIcon = computed(() =>
    this._isDark() ? 'bi-sun' : 'bi-moon',
  );

  constructor() {
    this.initializeTheme();
  }

  toggleTheme(): void {
    this._isDark.update((v) => !v);
    this.persistTheme();
    this.applyTheme();
  }

  setTheme(theme: 'dark' | 'light'): void {
    this._isDark.set(theme === 'dark');
    this.persistTheme();
    this.applyTheme();
  }

  refreshTheme(): void {
    this.applyTheme();
  }

  private initializeTheme(): void {
    const storedTheme = localStorage.getItem('vdin-theme');
    if (storedTheme !== null) {
      this._isDark.set(storedTheme === 'dark');
    } else {
      this._isDark.set(
        window.matchMedia('(prefers-color-scheme: dark)').matches,
      );
      this.listenToOsChanges();
    }
    this.applyTheme();
  }

  private listenToOsChanges(): void {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    mediaQuery.addEventListener('change', (e) => {
      if (localStorage.getItem('vdin-theme') !== null) return;
      this._isDark.set(e.matches);
      this.applyTheme();
    });
  }

  private persistTheme(): void {
    localStorage.setItem('vdin-theme', this.theme());
  }

  private applyTheme(): void {
    this.document.documentElement.setAttribute(
      'data-bs-theme',
      this.theme(),
    );
  }
}
